#!/usr/bin/env python3
"""Builds .ufo/waves/round-73/w1-spec.json (tabi round 73, one v1 wave of 11 seats).
Reads the freeze facts (D, pins, nonce) from committed files so nothing is hand-transcribed."""
import json, pathlib, re
L = '/home/vgpnk/Projects/shokunin/tabi-shokunin'
R = L + '/.ufo/waves/round-73'
W = R + '/w1'
SC = '/fast/scratch/hyaku/tabi-r73'
DIRECTIVE = pathlib.Path('/home/vgpnk/.agents/skills/godspeed/directive.md').read_text()
FZ = pathlib.Path(R + '/freeze.txt').read_text()
pins = dict((p, h) for h, p in re.findall(r'^([0-9a-f]{64})  (\S+)$', FZ, re.M))
PIN_D = pins['scripts/chrome-cdp-synthpinch-round73.mjs']
PIN_C = pins['scripts/check-synthpinch-r73.mjs']
D = pathlib.Path(R + '/scored/digests-commit.txt').read_text().split()[0]
D12 = D[:12]
NA = 'tabi-r73-l1-' + D12
NB = 'tabi-r73-exec1-' + D12
EV = L + '/corpus/evidence/round73/chromium-synth-pinch-gesture/receipt.json'
C1D = R + '/controls/c1'
PRE = [f'{C1D}/smoke{i}.receipt.json' for i in range(1, 10)] + [f'{C1D}/degenerate-{k}.receipt.json' for k in ['dispatch-wheel', 'set-scale', 'skip-touch']]
PP = ' '.join('--prior ' + p for p in PRE)
DEG = ' '.join(f'--laundered {C1D}/degenerate-{k}.receipt.json' for k in ['dispatch-wheel', 'set-scale', 'skip-touch'])
STATUS = pathlib.Path(R + '/scored/status-at-dispatch.txt').read_text().strip()

context = f"""# Target
Tabi round 73, one v1 wave w1. L1 TabiR73 holds the planner seat and is the sole integration owner. Lane {L}; base d7ff9f190260d91a1e675f474b7abf79960cdfd4. Claim FROZEN in {R}/claims.json; instrument digests in {R}/freeze.txt, digests commit D = {D}. Never propose amending the predicate, counter, pins or kill rule; attack them.
C1 coverage, capability re-claim chromium-synth-pinch-gesture-linux (CDP Input.synthesizePinchGesture on Chromium 155 headless), generation r73: driver {L}/scripts/chrome-cdp-synthpinch-round73.mjs (sha256 {PIN_D}), counter {L}/scripts/check-synthpinch-r73.mjs (sha256 {PIN_C}, 98 checks; REQUIRES --expect-driver-sha256, --expect-nonce and >= 1 --prior), battery {L}/scripts/negatives-synthpinch-r73.mjs (refusal cases pass only if the expected id fires with no undeclared co-firing id; must-accept cases; laundered degenerates), kill-power control {C1D}/kill-power-r73.mjs (98 force-true + 19 source-location semantic mutants incl. M5 producer-verdict AND->OR). New in r73 over r72: absolute anchor cases (r72 closure routed defect 1) and replay refusal (routed defect 2): checks nonce-expected, replay-launch-token, replay-devtools-url, replay-event-timeline against --prior receipts. Declared limit: a forger who rewrites nonce, launch token, DevTools browser id and every event ts of a prior receipt is not refused (controls/c1/controls-summary.json limit-full-identifier-rewrite exit 0).
PRE (the 12 committed pre-freeze receipts, the frozen prior set) as arguments: {PP}
Predicate C1-SYNTHPINCH-R73: (a) L1 post-D scored run, nonce {NA}, counter exit 0 clean with PRE priors, receipt {EV}; (b) independent cold run by R73Exec1, nonce {NB}, counter clean with PRE priors plus the (a) receipt as 13th prior; (c) battery exit 0 AND kill power holds on the (a) receipt; (d) capability row 0->1 + r73 knowledge note citing S180-S183.
STATUS AT DISPATCH (measured by the L1, committed in {R}/scored/): {STATUS}
Pre-freeze evidence: counter, battery and kill power over all 9 smoke receipts ({C1D}/prefreeze-summary.json); do-nothing/forgery controls {C1D}/controls-summary.json.
New sources this round: S180 web_mouse_wheel_event.cc, S181 wheel_event.cc, S182 web_input_event_conversion.cc, S183 local_frame_view.cc, all Chromium tag 155.0.8059.84, staged in {R}/sources/ (rows {L}/corpus/SOURCES.md S180-S183). Knowledge note {L}/corpus/knowledge/chromium-synth-pinch-gesture-runtime-round-73.md.
Prior closures to learn from: {L}/corpus/lessons/round-72-verifier-spotcheck.md, round-71-verifier-spotcheck.md, round-62-verifier-spotcheck.md.
# Bounds
All paths absolute. Write ONLY inside your own {W}/<your name>/ directory (reports, receipts, proposed files); never production, lane-root, fleet or sibling files. Every `Report:` trailer path is relative to {L} -- write it at {L}/<that path>, NEVER under the fleet root /home/vgpnk/Projects/shokunin. No git/jj mutations, commits or pushes anywhere; read-only git only (git -C <repo> show/log/rev-parse/status). Any fixture repo: D=$(mktemp -d -p {SC}) && git -C "$D" init -q, every later call names -C "$D". One integration owner (the L1). No delegation, no swarms, no task calls. Never mutate host sysctls or services. Scratch: {SC}/<your name>/ (mkdir -p; pass it explicitly as TMPDIR / --scratch / --work); keep it SHORT (Chromium's singleton socket path must stay under 107 bytes: the driver refuses longer scratch paths); copy receipts into your wave dir first, then delete your scratch before you yield (trap 'rm -rf -- "$S"' EXIT). /tmp only for files under 50 MB, never cited.
Tooling: you may install or upgrade tools that help the task -- first read /home/vgpnk/.omp/agent/RULES.md (official channels, update-safety gate; record tool/version/channel/reason). pacman guard: all pacman transactions are PAUSED host-wide; install via uv tool / npx / an official binary in ~/.local/bin, never -Sy/-Syu/-U/-R. Record every install in your report.
# Output
Your report's first line is one verdict word (HOLDS, FALSIFIED, FINDINGS, CONFIRMED, REFUTED, DONE or BLOCKED). Every claim in it carries a command and its exit code or a path:line. Unrun = not passed."""

def item(name, role, axes, milestone, body):
    return {"name": name, "role": role, "axes": axes, "milestone": milestone,
            "prompt": "/skill:godspeed\n\n" + DIRECTIVE + "\n# Assignment\n" + body.strip() + f"\n\nWrite {W}/{name}/report.md (first line: verdict word), plus any receipts beside it."}

items = [
 item("R73Exec1", "executor", ["coverage"], "Predicate leg (b): independent cold run, plus independent re-run of leg (c)", f"""
Check the pinned digests first: sha256sum every file listed in {R}/freeze.txt and compare; report each.
Leg (b): run the pinned driver ONCE cold: mkdir -p {SC}/R73Exec1/d && node {L}/scripts/chrome-cdp-synthpinch-round73.mjs --scratch {SC}/R73Exec1/d --out {W}/R73Exec1/receipt.json --nonce {NB} --http-port <free p1> --cdp-port <free p2> ; capture rc on the very next line. Only if that rc is 2 AND no receipt was written (usage refusal before launch) may you re-run with new ports; any receipt written is final. Then node {L}/scripts/check-synthpinch-r73.mjs --receipt {W}/R73Exec1/receipt.json --expect-driver-sha256 {PIN_D} --expect-nonce {NB} {PP} --prior {EV} --json > {W}/R73Exec1/counter.json ; rc on the next line.
Leg (c), independently, on the L1's scored receipt: node {L}/scripts/negatives-synthpinch-r73.mjs --real {EV} --expect-driver-sha256 {PIN_D} --expect-nonce {NA} {PP} --work {SC}/R73Exec1/n {DEG} --json > {W}/R73Exec1/negatives-a.json ; rc. Then the battery on YOUR receipt (--real {W}/R73Exec1/receipt.json --expect-nonce {NB}, priors PRE plus --prior {EV}) > {W}/R73Exec1/negatives-b.json ; rc. Then node {C1D}/kill-power-r73.mjs --lane {L} --real {EV} --expect-driver-sha256 {PIN_D} --expect-nonce {NA} {PP} --work {SC}/R73Exec1/k --out {W}/R73Exec1/kill-power-a.json --jobs 6 ; rc. Report: driver rc, counter verdict/checkCount/findings, battery passed/cases/failed for both receipts, kill power forceTrue/semantic/survivors/holds. State plainly whether legs (b) and (c) hold as frozen."""),
 item("R73Exec2", "executor", ["coverage", "calibration"], "Post-freeze repetition red rate over fresh cold runs", f"""
Run the pinned driver 3 times cold (nonces tabi-r73-exec2-<n>-<8 hex>, own free ports, scratch {SC}/R73Exec2/d<n>, receipts {W}/R73Exec2/d<n>.receipt.json). On each: counter (--expect-driver-sha256 {PIN_D} --expect-nonce <its nonce> {PP} --prior {EV}) and battery (same pin/nonce/priors, --work {SC}/R73Exec2/w<n>, {DEG}). Tabulate per-check counter red rate and per-case battery failure rate over these 3 receipts plus the 9 pre-freeze smokes (their pre-freeze results are {C1D}/pf-smoke<n>.counter.json / .battery.json). For every battery case whose mutation is relative to an honest receipt value (+=, -=, *=), report the margin by which it crosses the counter's tolerance on each of the 12 receipts and flag any margin under 2x the observed honest spread. Also record the first in/default wheel clientX/clientY per receipt."""),
 item("R73Review1", "reviewer", ["coverage"], "False greens in check-synthpinch-r73.mjs, focused on the r73 replay and nonce binding", f"""
Review {L}/scripts/check-synthpinch-r73.mjs at its frozen bytes (sha256 {PIN_C}). Craft receipts in your scratch from {EV} and the PRE receipts (never edit the scripts) and score them with the pinned counter. Priority: (1) the replay checks: any replay of a PRE receipt that keeps one of launch token / DevTools browser id / event timeline but is still accepted (e.g. reorder events, perturb one ts by 1e-12, case-change the uuid, add whitespace to the url, insert a no-op event, change only `at`); (2) nonce binding: nonce-expected vs nonce-on-page vs server-log vs the navigate URL and ready expression; (3) argv parsing: --prior with a missing value, duplicated flags, `--prior --json`, a prior that equals the receipt path, flags after --json; (4) the r72 R72Review1 FG2-FG11 classes re-checked on r73 bytes (send-log order, clocks, host version, fixture, law-consistent fabricated content). For each false green: command, exit, findings, and whether it is inside the declared limit in {R}/claims.json."""),
 item("R73Review2", "reviewer", ["coverage", "calibration"], "Battery and kill-power review: absolute anchors, isolation, robustness", f"""
Review {L}/scripts/negatives-synthpinch-r73.mjs and {C1D}/kill-power-r73.mjs at their frozen bytes ({R}/freeze.txt). (1) QUALITY 135 ({L}/corpus/QUALITY.md item 135): re-run the battery on 3 of the 9 PRE smokes of your choice (priors = the other 11 PRE receipts, --expect-nonce from {C1D}/smoke<n>.args.txt first field) and compare with the committed pf-smoke<n>.battery.json. Is every refusal case's mutation absolute or shown to cross its tolerance on every PRE receipt? (2) Isolation: can any refusal case pass with its expected id absent (alsoAllowed too wide)? Does any must-accept case accept a dishonest receipt? Are the replay cases each isolated? (3) Kill power: are the 19 semantic mutants meaningful edits, and does each new r73 one (nonce-expected, replay every->some, token shape, url dropped, timeline at-only, anchor tolerance 2) die for the reason intended (name the case that kills it)? Report findings with commands and exit codes."""),
 item("R73Review3", "reviewer", ["calibration"], "Conformance: freeze ordering, pins, nonce derivation, before->after", f"""
Read-only conformance review of round 73's C1 against its own rules. (1) Ordering: git -C {L} log --format='%H %ci %s' d7ff9f19..HEAD -- .ufo/waves/round-73 scripts corpus SCORECARD.md: the pre-freeze controls commit precedes the claims.json commit, which precedes D (freeze.txt), which precedes the scored receipt commit. (2) Pins: sha256 of every file named in freeze.txt at D and at the current tip equal the recorded digests. (3) Nonce: the scored receipt's nonce equals tabi-r73-l1-<first 12 hex of D> and no PRE receipt or file committed before D contains that string (git -C {L} grep at the pre-freeze commit). (4) Before->after: re-run the before commands in claims.json ('before' block) at base d7ff9f19 (git show / git -C worktree in {SC}/R73Review3) and the after counting command at the tip; report exit codes. (5) Is every claim in {R}/claims.json measurable by one command over committed bytes? Name any leg that is an assertion the counter cannot measure."""),
 item("R73Critic", "critic", ["coverage"], "Falsify the claim: do-nothing reach, replay, honest limits", f"""
Attack {R}/claims.json. (1) Could a do-nothing or look-alike producer meet legs (a)-(c) as frozen? Build the cheapest forgery you can (replay of a PRE receipt with a minimal edit, an R72-generation receipt relabelled, a synthesised receipt) and score it with the pinned counter using the frozen arguments; say whether your forgery is inside or outside the declared limit. (2) Is the limit sentence complete and honest (compare with what the counter actually reads)? (3) Is C1 named by the surface it moves (coverage: a capability row for a command no tabi row covers), and is the 'sourced' field true: do S180-S183 (staged {R}/sources/) actually ground sum(deltaY*scale) = -100 ln(scaleFactor), or is a link still inference? (4) Is anything in the predicate satisfiable without the round's work (the r72 instruments, the r72 receipts)? Verdict HOLDS or FALSIFIED with evidence."""),
 item("R73Mut1", "mutation-tester", ["coverage"], "Semantic mutants beyond the 19 frozen ones", f"""
Copy {L}/scripts/check-synthpinch-r73.mjs and negatives-synthpinch-r73.mjs to {SC}/R73Mut1/s/. Generate >= 25 single-edit semantic mutants of the counter that are NOT among the 19 in {C1D}/kill-power-r73.mjs and do not simply force a check true; include R72Mut1's 13 r72 survivors re-targeted at r73 bytes (in-span lower bound, zero-span upper bound, non-first pinch params, empty-params allow-set, leg-mark monotonicity, once() for Browser.getVersion and setDeviceMetricsOverride, loose error message, some() server-log binding, seq start, deltaMode type, CDP initial scale) and new ones on the replay code (browserId regex, timeline JSON shape, priors loop). For each, run the battery COPY beside it: node <copy>/negatives-synthpinch-r73.mjs --real {EV} --expect-driver-sha256 {PIN_D} --expect-nonce {NA} {PP} --work {SC}/R73Mut1/w<k> --json; killed = exit 1. Table: mutant, edit (exact from/to), killed, failed cases. For each survivor: a crafted receipt the pristine counter refuses but the mutant accepts (or say it is equivalent)."""),
 item("R73Scout", "scout", ["coverage", "depth"], "Independently open S180-S183 and the emulation factor", f"""
Independently fetch, this session, base64 ?format=TEXT, decode: https://chromium.googlesource.com/chromium/src/+/refs/tags/155.0.8059.84/<path>?format=TEXT for third_party/blink/common/input/web_mouse_wheel_event.cc, third_party/blink/renderer/core/events/wheel_event.cc, third_party/blink/renderer/core/events/web_input_event_conversion.cc, third_party/blink/renderer/core/frame/local_frame_view.cc. Record access time, sha256 and line count, and `cmp` each with the L1-staged copy in {R}/sources/. Locate and quote (<= 25 words each, with line numbers) the lines cited in {L}/corpus/SOURCES.md rows S180-S183 and in {L}/corpus/knowledge/chromium-synth-pinch-gesture-runtime-round-73.md; report any anchor that is off. Then find where InputEventsScaleForEmulation() is implemented for the headless/content embedder at this tag (e.g. third_party/blink/renderer/core/page/chrome_client_impl.cc or web_view_impl.cc), quote it, and say whether it is 1 when Emulation.setDeviceMetricsOverride sets no `scale`. That would source the note's remaining inference; propose a registry row (do not edit the registry)."""),
 item("R73Connector", "connector", ["adjacency"], "Sibling overlap scan for Blink wheel-delta and page-scale sources", f"""
Scan sibling lanes under /home/vgpnk/Projects/shokunin/*-shokunin (read-only) for knowledge, SOURCES rows or scripts overlapping tabi's r73 ground: web_mouse_wheel_event.cc, wheel_event.cc, web_input_event_conversion.cc, local_frame_view.cc, InputEventsScaleFactor, DeltaYInRootFrame, visualViewport scale, synthesizePinchGesture, ctrl+wheel zoom. For each hit: lane, path:line, quote <= 25 words, whether it is contested scope against tabi's PROVINCE ({L}/PROVINCE.md) and whether it is a duplicate-URL risk for S180-S183 (sources-census W04). Output a table and a one-line verdict (overlap none / adjacent / contested)."""),
 item("R73Scribe", "scribe", ["depth"], "Independent re-derivation of the r73 knowledge note and lesson Gate", f"""
Read {L}/corpus/knowledge/chromium-synth-pinch-gesture-runtime-round-73.md and the staged sources in {R}/sources/. Independently re-derive (with node/python over the receipts, show the command): the per-leg sums of deltaY*scale and raw deltaY over the 9 PRE smokes and the (a) receipt {EV}, the largest deviation from -100 ln(factor), and the first in/default wheel clientX distribution. Check every number and every quoted line in the note against your derivation and the sources. Draft, in {W}/R73Scribe/, (1) note-review.md: agree/disagree per statement with evidence; (2) gate-draft.md: a lesson `## Gate` block for S180-S183 (URL, access date, <= 25-word located quote per row) plus one admit and one reject decision a non-author could spot-check."""),
 item("R73Revenger", "revenger", ["calibration"], "Fresh-start audit: does r73 repeat a rejected root failure?", f"""
Read the non-author spotchecks {L}/corpus/lessons/round-60-verifier-spotcheck.md, round-61-, round-62-, round-71- and round-72-verifier-spotcheck.md and the MANIFEST closure rows for tabi r60-r72 (/home/vgpnk/Projects/shokunin/MANIFEST.json, read-only; rounds array entries with lane tabi). For each root failure (K7 no-regression conjunct; frozen header rejected; post-scoring recorder/interface changes; M5 AND->OR survivor; contradictory duplicate/fabricated dispositions; r71 leg-b relabel leak; r72 relative battery case and replay hole), determine from committed r73 bytes whether round 73 repeats it, closes it, or leaves it open: cite path:line or a command and its output. Also check the SCORECARD/SHONEN self-assessment against repo state: count mismatches (calibration) between {L}/SHONEN.md / SCORECARD.md claims and what the repo shows."""),
]
spec = {"wave": "w1", "milestone": "Round73 post-freeze: independent leg (b), leg (c) re-run, repetition, replay/limit attacks, sources re-open; 11 seats, 5 attack roles (3 reviewer, 1 critic, 1 mutation-tester) + revenger audit, L1 planner",
        "reportDir": ".ufo/waves/round-73/w1", "context": context, "items": items}
pathlib.Path(R + '/w1-spec.json').write_text(json.dumps(spec, indent=1, ensure_ascii=False) + "\n")
print(len(items), NA, NB)
